mapper.select:
SELECT p.id,p.author_principal_id,p.display_mode,CASE WHEN p.display_mode='account' THEN pr.account_id END AS author_account_id,CASE WHEN p.display_mode='account' THEN COALESCE((SELECT nickname FROM profiles WHERE account_id=pr.account_id AND visibility='public' AND moderation_status='approved' LIMIT 1),'Youren用户') END AS author_nickname,p.title,p.body,p.category,p.region_code,p.status,p.published_at,p.expires_at,p.version
FROM posts p LEFT JOIN principals pr ON pr.id=p.author_principal_id
WHERE p.status='visible' AND p.scope='public' AND p.deleted_at IS NULL AND p.expires_at>#{now}
AND p.region_code=#{regionCode}
AND p.category=#{category}
AND (p.title ILIKE '%' || #{query} || '%' OR p.body ILIKE '%' || #{query} || '%')
AND EXISTS(SELECT 1 FROM post_interests pi WHERE pi.post_id=p.id AND pi.interest_id=#{interestId})
AND (p.published_at,p.id)<(#{cursorTime},#{cursorId})
ORDER BY p.published_at DESC,p.id DESC LIMIT #{limit}

SELECT id,created_at FROM postscomments WHERE author_principal_id IN ()
    AND CASE WHEN status='deleted' THEN 'deleted' WHEN expires_at IS NOT NULL AND expires_at<=#{now} THEN 'expired' ELSE status END=#{status}
    AND (created_at,id)<(#{cursorTime},#{cursorId}) ORDER BY created_at DESC,id DESC LIMIT #{limit}
